        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i

import string

def word_frequency(text: str) -> dict[str, int]:
    freq = {}
    for word in text.split():
        word = word.strip(string.punctuation).lower()
        if word:
            freq[word] = freq.get(word, 0) + 1
    return freq
